`,paraId:19,tocIndex:13},{value:"\u5C5E\u6027",paraId:20,tocIndex:14},{value:"\u7C7B\u578B",paraId:20,tocIndex:14},{value:"\u9ED8\u8BA4\u503C",paraId:20,tocIndex:14},{value:"\u8BF4\u660E",paraId:20,tocIndex:14},{value:"ttl",paraId:20,tocIndex:14},{value:"number",paraId:20,tocIndex:14},{value:"-1",paraId:20,tocIndex:14},{value:"\u7F13\u5B58\u8FC7\u671F\u65F6\u95F4\uFF08\u6BEB\u79D2\uFF09\uFF0C-1 \u8868\u793A\u4E0D\u7F13\u5B58",paraId:20,tocIndex:14},{value:"interpretHeader",paraId:20,tocIndex:14},{value:"boolean",paraId:20,tocIndex:14},{value:"false",paraId:20,tocIndex:14},{value:"\u662F\u5426\u6839\u636E\u54CD\u5E94\u5934\u7F13\u5B58\u7B56\u7565",paraId:20,tocIndex:14},{value:"methods",paraId:20,tocIndex:14},{value:"string[]",paraId:20,tocIndex:14},{value:"['get', 'post', 'head']",paraId:20,tocIndex:14},{value:"\u5141\u8BB8\u53C2\u4E0E\u7F13\u5B58\u7684 HTTP \u65B9\u6CD5",paraId:20,tocIndex:14},{value:"\u9ED8\u8BA4\u5F00\u542F\uFF08",paraId:21,tocIndex:15},{value:"bigIntJSONParsing: true",paraId:21,tocIndex:15},{value:"\uFF09\uFF0C\u81EA\u52A8\u68C0\u6D4B\u8D85\u8FC7\u5B89\u5168\u8303\u56F4\u7684\u6570\u5B57\u5E76\u4FDD\u7559\u7CBE\u5EA6\u3002",paraId:21,tocIndex:15},{value:`// \u540E\u7AEF\u8FD4\u56DE {"id": 9007199254740993}
