// data.id === "9007199254740993"
`,paraId:22,tocIndex:15},{value:`// \u5173\u95ED\u5927\u6570\u89E3\u6790
request.setConfig({ bigIntJSONParsing: false })

// \u81EA\u5B9A\u4E49\u89E3\u6790\u5668
request.setConfig({
  bigIntJSONParsing: true,
  bigIntNumberParser: (key, str) => {
    // \u81EA\u5B9A\u4E49\u5927\u6570\u5904\u7406\u903B\u8F91
    return BigInt(str)
  },
})
