export default () => (
  <ProTable
    editFields={[
      { label: '\u6587\u672C', name: 'text' },
      {
        label: '\u5355\u9009\u6846', name: 'select', type: 'select',
        options: [
          { label: '\u9009\u98791', value: 1 },
          { label: '\u9009\u98792', value: 2 },
        ],
      },
    ]}
    columnActions={['edit']} // \u5F00\u542F\u7F16\u8F91\u52A8\u4F5C\uFF08\u5F39\u7A97\uFF09
    columns={[
      {
        title: '\u6587\u672C',
        dataIndex: 'text',
        width: '50%',
      },
      {
        title: '\u5355\u9009\u6846',
        dataIndex: 'select',
        width: '50%',
        valueType: 'select',
        valueEnum: [
          { label: '\u9009\u98791', value: 1 },
          { label: '\u9009\u98792', value: 2 },
        ],
      },
    ]}
    onView={async (item) => {
      const details = await axios.get('SERVER_DETAILS', { id: item.id })

      return {
        data: { ...item, ...details },
        success: true
      }
    }}
    onEdit={async (params, item) => {
      await axios.post('SERVER_URL', {
        id: item?.id,
        ...params
      })

      return { success: true, message: '\u7F16\u8F91\u6210\u529F' }
    }}
  />
)
